package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.IdTokenEncryptedResponseAlgVO;

class IdTokenEncryptedResponseAlgValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of id token encrypted response alg of oauth client")
  void test_id_token_encrypted_response_alg_value_holder_assign_plain_value() {
    Object holder = new Object();
    IdTokenEncryptedResponseAlgValueHolder<Object> value =
        new IdTokenEncryptedResponseAlgValueHolder<>(holder);
    Assertions.assertSame(holder, value.idTokenEncryptedResponseAlg("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getIdTokenEncryptedResponseAlgValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getIdTokenEncryptedResponseAlg().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.idTokenEncryptedResponseAlgNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getIdTokenEncryptedResponseAlgValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getIdTokenEncryptedResponseAlg().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of id token encrypted response alg of oauth client")
  void test_id_token_encrypted_response_alg_value_holder_assign_value_object() {
    Object holder = new Object();
    IdTokenEncryptedResponseAlgValueHolder<Object> value =
        new IdTokenEncryptedResponseAlgValueHolder<>(holder);
    IdTokenEncryptedResponseAlgVO vo = IdTokenEncryptedResponseAlgVO.from("one");
    Assertions.assertFalse(value.getIdTokenEncryptedResponseAlgValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.idTokenEncryptedResponseAlg(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getIdTokenEncryptedResponseAlgValue().orElseThrow());
    Assertions.assertSame(holder, value.idTokenEncryptedResponseAlg(Optional.empty()));
    Assertions.assertFalse(value.getIdTokenEncryptedResponseAlgValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.idTokenEncryptedResponseAlg(Optional.of(vo)));
    Assertions.assertSame(vo, value.getIdTokenEncryptedResponseAlgValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of id token encrypted response alg of oauth client against the original")
  void test_id_token_encrypted_response_alg_value_holder_read() {
    Object holder = new Object();
    IdTokenEncryptedResponseAlgValueHolder<Object> value =
        new IdTokenEncryptedResponseAlgValueHolder<>(holder);
    IdTokenEncryptedResponseAlgVO vo = IdTokenEncryptedResponseAlgVO.from("one");
    IdTokenEncryptedResponseAlgVO other = IdTokenEncryptedResponseAlgVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getIdTokenEncryptedResponseAlgValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other,
        value.readIdTokenEncryptedResponseAlg(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readIdTokenEncryptedResponseAlg(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.idTokenEncryptedResponseAlg(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readIdTokenEncryptedResponseAlg(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readIdTokenEncryptedResponseAlg(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of id token encrypted response alg of oauth client")
  void test_id_token_encrypted_response_alg_value_holder_unset() {
    Object holder = new Object();
    IdTokenEncryptedResponseAlgValueHolder<Object> value =
        new IdTokenEncryptedResponseAlgValueHolder<>(holder);
    IdTokenEncryptedResponseAlgVO vo = IdTokenEncryptedResponseAlgVO.from("one");
    value.idTokenEncryptedResponseAlg(vo);
    Assertions.assertSame(holder,
        value.unsetIdTokenEncryptedResponseAlgIfMatches("idTokenEncryptedResponseAlg_other"));
    Assertions.assertTrue(value.getIdTokenEncryptedResponseAlgValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetIdTokenEncryptedResponseAlgIfMatches("idTokenEncryptedResponseAlg"));
    Assertions.assertFalse(value.getIdTokenEncryptedResponseAlgValue().isPresent(),
        "The field name must clear the value");
    value.idTokenEncryptedResponseAlg(vo);
    Assertions.assertSame(holder, value.unsetIdTokenEncryptedResponseAlg());
    Assertions.assertFalse(value.getIdTokenEncryptedResponseAlgValue().isPresent(),
        "Unset must clear the value");
  }
}
